ALTER TABLE employee_payroll_profiles ADD COLUMN IF NOT EXISTS auto_calculate_contributions BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE employee_payroll_profiles ADD COLUMN IF NOT EXISTS employee_classification TEXT NOT NULL DEFAULT 'rank_and_file' CHECK(employee_classification IN ('rank_and_file','managerial'));
CREATE TABLE IF NOT EXISTS payroll_runs(id BIGSERIAL PRIMARY KEY,period_start DATE NOT NULL,period_end DATE NOT NULL,pay_date DATE NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','finalized','void')),created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(period_end>=period_start));
CREATE TABLE IF NOT EXISTS payroll_run_items(id BIGSERIAL PRIMARY KEY,run_id BIGINT NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE,employee_id BIGINT NOT NULL REFERENCES employee_profiles(id) ON DELETE RESTRICT,gross_compensation NUMERIC(14,2) NOT NULL,taxable_compensation NUMERIC(14,2) NOT NULL,non_taxable_compensation NUMERIC(14,2) NOT NULL,sss_employee NUMERIC(14,2) NOT NULL,philhealth_employee NUMERIC(14,2) NOT NULL,pagibig_employee NUMERIC(14,2) NOT NULL,union_dues NUMERIC(14,2) NOT NULL,tax_withheld NUMERIC(14,2) NOT NULL,net_pay NUMERIC(14,2) NOT NULL,calculation JSONB NOT NULL,UNIQUE(run_id,employee_id));
CREATE INDEX IF NOT EXISTS payroll_run_items_employee_idx ON payroll_run_items(employee_id,run_id);
